-- This program creates the listings table for LST-01 supplier listing
-- management. Availability slots are a later migration; this table
-- stores the listing itself.
--
-- File:   V2__create_listings_table.sql
-- Course: AUCSC 325 
--    

CREATE TABLE listings (
    -- To identify each listing; generated by the database
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- To store the display name shown in search and booking
    title       VARCHAR(255) NOT NULL,
    -- To store the category used by LST-02 filters
    category    VARCHAR(255) NOT NULL,
    -- To store money with two decimal places
    price       NUMERIC(10, 2) NOT NULL,
    -- To point at the owning supplier for LST-01 ownership checks
    supplier_id BIGINT NOT NULL,
    -- To deactivate a listing without deleting its row
    active      BOOLEAN NOT NULL DEFAULT TRUE,
    -- To reject a negative price at the database
    CONSTRAINT ck_listings_price_non_negative CHECK (price >= 0),
    -- To keep a listing only when its supplier account still exists
    CONSTRAINT fk_listings_supplier
        FOREIGN KEY (supplier_id) REFERENCES users (id)
);

-- To look up a supplier's listings when checking ownership
CREATE INDEX idx_listings_supplier_id ON listings (supplier_id);
